export function groupBy(items, key) {
  const groups = {};
  for (const item of items) {
    const value = item[key];
    if (!Object.prototype.hasOwnProperty.call(groups, value)) {
      groups[value] = [];
    }
    groups[value].push(item);
  }
  return groups;
}
